import { Router } from 'express';

const router = Router();

// o "banco de dados" da aula: uma lista em memória
const usuarios = [
  { id: 1, nome: 'Ana' },
  { id: 2, nome: 'Bia' },
];

// 1. GET /api/usuarios — devolve a lista inteira
router.get('/', (req, res) => {
  res.json(usuarios);
});

// 2. GET /api/usuarios/:id — devolve UM usuário
//    Number() transforma o texto do params em número, para comparar com o id.
router.get('/:id', (req, res) => {
  const id = Number(req.params.id);
  const usuario = usuarios.find((u) => u.id === id);

  // 3. Não achou: 404 com corpo JSON — o cliente sabe o que aconteceu.
  if (!usuario) {
    res.status(404).json({ erro: 'usuário não encontrado' });
    return;
  }

  // 4. Achou: 200 com o usuário em JSON.
  res.json(usuario);
});

export default router;
